function clearOneTimeSecrets(){const token=$('generatedToken'),recovery=$('generatedRecoveryKey');if(token)token.value='';if(recovery)recovery.value='';$('generatedTokenBox')?.classList.add('hidden');$('generatedRecoveryBox')?.classList.add('hidden');$('tokenCurrentPassword').value='';$('newApiToken').value='';$('recoveryCurrentPassword').value=''}
function setTab(id){if(uiState.activeTab==='settings'&&id!=='settings')clearOneTimeSecrets();uiState.activeTab=id;document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav-btn').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));const loaders={overview:loadOverview,integrations:loadIntegrations,logs:loadLogs,audit:loadAudit,events:loadEvents,approvals:loadApprovals,jobs:loadJobs,rules:loadRules,knowledge:loadKnowledge,skills:loadSkills,settings:loadSettings};if(loaders[id])loaders[id]()}
function bindEvents(){
  document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));
  $('logoutBtn').addEventListener('click',logout);$('sendBtn').addEventListener('click',sendChat);$('chatinput').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();sendChat()}});
  ['logLevel','logLimit'].forEach(id=>$(id).addEventListener('change',loadLogs));$('auditLimit').addEventListener('change',loadAudit);['logComponent','logQuery'].forEach(id=>$(id).addEventListener('keydown',e=>{if(e.key==='Enter')loadLogs()}));
  $('jobForm').addEventListener('submit',e=>{e.preventDefault();saveJob()});$('ruleForm').addEventListener('submit',e=>{e.preventDefault();saveRule()});$('approvalNotifyForm').addEventListener('submit',e=>{e.preventDefault();saveApprovalNotification()});
  $('skillForm').addEventListener('submit',e=>{e.preventDefault();saveSkill()});$('skillSearch').addEventListener('input',renderSkillsManage);$('skillStatusFilter').addEventListener('change',renderSkillsManage);
  $('jobtype').addEventListener('change',syncJobScheduleHint);syncJobScheduleHint();
  [['approvalNotifyChannel','approvalZaloThreadField'],['jobNotifyChannel','jobZaloThreadField'],['ruleNotifyChannel','ruleZaloThreadField'],['knowledgeNotifyChannel','knowledgeZaloThreadField']].forEach(([channel,field])=>$(channel).addEventListener('change',()=>syncNotificationThreadField(channel,field)));syncAllNotificationThreadFields();
  $('knowledgeSearchForm').addEventListener('submit',e=>{e.preventDefault();searchKnowledge()});$('knowledgeConfigForm').addEventListener('submit',e=>{e.preventDefault();saveKnowledgeConfig()});
  $('knowledgeDraftForm').addEventListener('submit',e=>{e.preventDefault();createKnowledgeDraft()});$('knowledgeLoadFileBtn').addEventListener('click',loadKnowledgeFile);$('knowledgeDraftPath').addEventListener('input',()=>{$('knowledgeDraftSource').textContent=knowledgeUI.loadedSource?.path===$('knowledgeDraftPath').value.trim()?'Nguồn đã tải · hash '+(knowledgeUI.loadedSource.sha256||'file mới'):'Chưa tải nguồn cho đường dẫn này.'});
  $('tokenForm').addEventListener('submit',e=>{e.preventDefault();saveApiToken(false)});$('generateTokenBtn').addEventListener('click',()=>saveApiToken(true));$('copyGeneratedToken').addEventListener('click',async()=>{const el=$('generatedToken');try{await copyTextSafe(el.value,el);toast('Đã sao chép token')}catch(err){toast(err.message||'Không thể sao chép tự động.',true)}});
  $('recoveryForm').addEventListener('submit',e=>{e.preventDefault();rotateRecoveryKey()});$('copyGeneratedRecoveryKey').addEventListener('click',async()=>{const el=$('generatedRecoveryKey');try{await copyTextSafe(el.value,el);toast('Đã sao chép Recovery Key')}catch(err){toast(err.message||'Không thể sao chép tự động.',true)}});
  $('usernameForm').addEventListener('submit',e=>{e.preventDefault();changeUsernameSubmit()});$('passwordForm').addEventListener('submit',e=>{e.preventDefault();changePasswordSubmit()});
  document.addEventListener('submit',e=>{
    const createForm=e.target.closest('[data-custom-integration-create]');if(createForm){e.preventDefault();createCustomIntegration(createForm);return}
    const customForm=e.target.closest('[data-custom-integration-form]');if(customForm){e.preventDefault();saveCustomIntegration(customForm.dataset.customIntegrationForm,customForm);return}
    const form=e.target.closest('[data-integration-form]');if(!form)return;e.preventDefault();saveIntegration(form.dataset.integrationForm,form)
  });
  document.addEventListener('click',e=>{const log=e.target.closest('.log-row');if(log){toggleLogDetail(log.dataset.logIndex);return}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;const actions={'overview-refresh':loadOverview,'skills-open':()=>setTab('skills'),'skills-refresh':loadSkills,'skill-new':newSkill,'skill-validate':validateSkillDraft,'new-session':newSession,'integrations-refresh':loadIntegrations,'integration-add':openIntegrationAddPanel,'logs-refresh':loadLogs,'logs-export':exportLogs,'audit-refresh':loadAudit,'events-refresh':loadEvents,'approvals-refresh':loadApprovals,'jobs-refresh':loadJobs,'rules-refresh':loadRules,'knowledge-refresh':loadKnowledge,'knowledge-scan':scanKnowledge,'knowledge-reindex':reindexKnowledge,'knowledge-search':searchKnowledge,'settings-refresh':loadSettings,'sessions-refresh':loadSessions,'sessions-revoke-others':revokeOtherSessions,'auth-audit-refresh':loadAuthAudit};if(actions[a]){actions[a]();return}if(a==='skill-edit'){editSkill(id);return}if(a==='skill-edit-cancel'){resetSkillForm();return}if(a==='skill-test'){testSkillUI(id);return}if(a==='skill-versions'){loadSkillVersions(id);return}if(a==='skill-toggle'){toggleSkillUI(id,b.dataset.enabled==='1');return}if(a==='skill-delete'){deleteSkillUI(id);return}if(a==='skill-rollback'){rollbackSkillUI(id,Number(b.dataset.version));return}if(a==='knowledge-review'){if(!knowledgeUI.busy.has('proposal'))reviewKnowledgeProposal(id);return}if(['knowledge-dry-run','knowledge-approve','knowledge-reject','knowledge-rollback'].includes(a)){knowledgeProposalAction(a.slice('knowledge-'.length),id);return}if(a==='approval-approve')decideApproval(id,true);if(a==='approval-reject')decideApproval(id,false);if(a==='jobs-page')loadJobs(Number(b.dataset.page));if(a==='rules-page')loadRules(Number(b.dataset.page));if(a==='job-edit')editJob(Number(id));if(a==='job-edit-cancel')resetJobForm();if(a==='job-toggle')toggleJob(Number(id),b.dataset.enabled==='1');if(a==='job-delete')deleteJob(Number(id));if(a==='rule-edit')editRule(Number(id));if(a==='rule-edit-cancel')resetRuleForm();if(a==='rule-toggle')toggleRule(Number(id),b.dataset.enabled==='1');if(a==='rule-delete')deleteRule(Number(id));if(a==='integration-reset')resetIntegration(id);if(a==='integration-delete-custom')deleteCustomIntegration(id);if(a==='integration-add-cancel'){const panel=$('integrationAddPanel');if(panel)panel.open=false}});
}
async function start(){const ok=await initAuth();if(!ok)return;bindEvents();health();loadOverview();setInterval(health,30000);setInterval(()=>{if(uiState.activeTab==='logs'&&$('logAuto').checked)loadLogs()},5000)}
start().catch(e=>{toast(e.message||String(e),true);reportClientError('startup_error',e.message||String(e),e.stack||'')});
